46: // Describe returns a (multi-line) representation of the commit indexes for the
47: // given lookuper.
48: func (c MajorityConfig) Describe(l AckedIndexer) string {
49: 	if len(c) == 0 {
50: 		return "<empty majority quorum>"
51: 	}
52: 	type tup struct {
53: 		id  uint64
54: 		idx Index
55: 		ok  bool // idx found?
56: 		bar int  // length of bar displayed for this tup
57: 	}
58: 
59: 	// Below, populate .bar so that the i-th largest commit index has bar i (we
60: 	// plot this as sort of a progress bar). The actual code is a bit more
61: 	// complicated and also makes sure that equal index => equal bar.
62: 
63: 	n := len(c)
64: 	info := make([]tup, 0, n)
65: 	for id := range c {
66: 		idx, ok := l.AckedIndex(id)
67: 		info = append(info, tup{id: id, idx: idx, ok: ok})
68: 	}
69: 
70: 	// Sort by index
71: 	slices.SortFunc(info, func(a, b tup) int {
72: 		if n := cmp.Compare(a.idx, b.idx); n != 0 {
73: 			return n
74: 		}
75: 		return cmp.Compare(a.id, b.id)
76: 	})
77: 
78: 	// Populate .bar.
79: 	for i := range info {
80: 		if i > 0 && info[i-1].idx < info[i].idx {
81: 			info[i].bar = i
82: 		}
83: 	}
84: 
85: 	// Sort by ID.
86: 	slices.SortFunc(info, func(a, b tup) int {
87: 		return cmp.Compare(a.id, b.id)
88: 	})
89: 
90: 	var buf strings.Builder
91: 
92: 	// Print.
93: 	fmt.Fprint(&buf, strings.Repeat(" ", n)+"    idx\n")
94: 	for i := range info {
95: 		bar := info[i].bar
96: 		if !info[i].ok {
97: 			fmt.Fprint(&buf, "?"+strings.Repeat(" ", n))
98: 		} else {
99: 			fmt.Fprint(&buf, strings.Repeat("x", bar)+">"+strings.Repeat(" ", n-bar))
100: 		}
101: 		fmt.Fprintf(&buf, " %5d    (id=%d)\n", info[i].idx, info[i].id)
102: 	}
103: 	return buf.String()
104: }
